import express, { Router } from "express";
import { authenticate } from "../../middleware/authenticate.js";
import { validateParams } from "../../middleware/validate.js";
import { uploadLimiter } from "../../middleware/rateLimiter.js";
import AttachmentController from "./attachment.controller.js";
import { channelMessageParamsSchema } from "../messages/message.validation.js";

const router = Router();
const controller = new AttachmentController();

router.use(authenticate);
// Upload identifiers are generated by the server. Accepting a client-supplied
// ID would let a caller overwrite another user's object or traverse paths.
router.put(
  "/:channelId/uploads",
  uploadLimiter,
  validateParams(channelMessageParamsSchema),
  express.raw({ type: "application/octet-stream", limit: "10mb" }),
  controller.upload.bind(controller),
);

export default router;
